define(['core/log','mod_videotrack/core/confirm'],function(Log,Confirm){var attachConfirm=function(selector,fallbackMessage,labels){labels=labels||{};Confirm.attachToForms(selector,{message:fallbackMessage,okString:{key:'yes',component:'moodle'},fallbackLabels:{confirm:labels.confirm,ok:labels.yes,cancel:labels.cancel},logger:Log,logPrefix:'mod_videotrack/report'});};return{init:function(config){config=config||{};attachConfirm('.videotrack-reset-student-form',config.confirmreset,config.labels);attachConfirm('.videotrack-recalculate-form',config.confirmrecalculate,config.labels);Log.debug('mod_videotrack/report: initialised');}};});
